package com.campusconnect.dao;
import com.campusconnect.exception.DatabaseException; import com.campusconnect.model.LostFoundItem; import com.campusconnect.util.DatabaseConnection; import java.sql.*; import java.util.*;
public class LostFoundDAO { private LostFoundItem map(ResultSet r)throws SQLException{LostFoundItem x=new LostFoundItem();x.setId(r.getInt("id"));x.setPostedBy(r.getInt("posted_by"));x.setTitle(r.getString("title"));x.setDescription(r.getString("description"));x.setCategory(r.getString("category"));x.setLocation(r.getString("location"));x.setItemDate(r.getDate("item_date").toLocalDate());x.setStatus(r.getString("status"));x.setPosterName(r.getString("poster_name"));return x;}
 public List<LostFoundItem> findAll(String q,String cat){List<LostFoundItem>a=new ArrayList<>();String sql="SELECT l.*,s.name poster_name FROM lost_found_items l JOIN students s ON s.user_id=l.posted_by WHERE (l.title LIKE ? OR l.description LIKE ?) AND (?='All' OR l.category=?) ORDER BY l.item_date DESC";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){String x="%"+(q==null?"":q.trim())+"%";p.setString(1,x);p.setString(2,x);p.setString(3,cat);p.setString(4,cat);try(ResultSet r=p.executeQuery()){while(r.next())a.add(map(r));}}catch(SQLException e){throw new DatabaseException("Could not load lost/found items.",e);}return a;}
 public void insert(LostFoundItem x){String sql="INSERT INTO lost_found_items(title,description,category,location,item_date,status,posted_by) VALUES(?,?,?,?,?,?,?)";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){p.setString(1,x.getTitle());p.setString(2,x.getDescription());p.setString(3,x.getCategory());p.setString(4,x.getLocation());p.setDate(5,Date.valueOf(x.getItemDate()));p.setString(6,x.getStatus());p.setInt(7,x.getPostedBy());p.executeUpdate();}catch(SQLException e){throw new DatabaseException("Could not create post.",e);}}
 public void updateStatus(int id,String status){try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE lost_found_items SET status=? WHERE id=?")){p.setString(1,status);p.setInt(2,id);p.executeUpdate();}catch(SQLException e){throw new DatabaseException("Could not update item.",e);}}
 public void delete(int id){try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("DELETE FROM lost_found_items WHERE id=?")){p.setInt(1,id);p.executeUpdate();}catch(SQLException e){throw new DatabaseException("Could not delete item.",e);}} public int count(String status){try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT COUNT(*) FROM lost_found_items WHERE status=?")){p.setString(1,status);try(ResultSet r=p.executeQuery()){r.next();return r.getInt(1);}}catch(SQLException e){throw new DatabaseException("Could not read item statistics.",e);}}
}
